class Solution:
    def councilWinner(self, council: str) -> str:
        n = len(council)
        silenced = [False] * n
        active = {"L": council.count("L"), "O": council.count("O")}
        while True:
            for i, c in enumerate(council):
                if silenced[i]:
                    continue
                other = "O" if c == "L" else "L"
                if active[other] == 0:
                    return "Larks" if c == "L" else "Owls"
                j = (i + 1) % n
                while silenced[j] or council[j] != other:
                    j = (j + 1) % n
                silenced[j] = True
                active[other] -= 1

