class Solution {
    public String councilWinner(String council) {
        int n = council.length();
        boolean[] silenced = new boolean[n];
        int[] active = new int[2];
        for (int i = 0; i < n; i++) active[council.charAt(i) == 'L' ? 0 : 1]++;
        while (true) {
            for (int i = 0; i < n; i++) {
                if (silenced[i]) continue;
                char c = council.charAt(i);
                int me = c == 'L' ? 0 : 1, other = 1 - me;
                if (active[other] == 0) return me == 0 ? "Larks" : "Owls";
                int j = (i + 1) % n;
                while (silenced[j] || council.charAt(j) == c) j = (j + 1) % n;
                silenced[j] = true;
                active[other]--;
            }
        }
    }
}

