class Solution {
    public String councilWinner(String council) {
        int n = council.length();
        ArrayDeque<Integer> larks = new ArrayDeque<>(), owls = new ArrayDeque<>();
        for (int i = 0; i < n; i++) (council.charAt(i) == 'L' ? larks : owls).add(i);
        while (!larks.isEmpty() && !owls.isEmpty()) {
            int a = larks.poll(), b = owls.poll();
            if (a < b) larks.add(a + n);
            else owls.add(b + n);
        }
        return larks.isEmpty() ? "Owls" : "Larks";
    }
}

