class Solution {
public:
    string councilWinner(string& council) {
        int n = council.size();
        queue<int> larks, owls;
        for (int i = 0; i < n; i++) (council[i] == 'L' ? larks : owls).push(i);
        while (!larks.empty() && !owls.empty()) {
            int a = larks.front(), b = owls.front();
            larks.pop();
            owls.pop();
            if (a < b) larks.push(a + n);
            else owls.push(b + n);
        }
        return larks.empty() ? "Owls" : "Larks";
    }
};

